define("mod_pptbook/lightbox", ["jquery"], function($) {
    'use strict';

    const SEL_link  = ".pptbook-zoom";
    const SEL_modal = "#pptbook-modal";
    const SEL_img   = "#pptbook-modal-img";
    const SEL_prev  = "#pptbook-modal-prev";
    const SEL_next  = "#pptbook-modal-next";

    let items = [];
    let startIndex = 0;
    let current = -1;

    function initData() {
        // Читаем JSON со всеми картинками
        const $data = $("#pptbook-all-items");
        if ($data.length) {
            try {
                items = JSON.parse($data.text());
                // Читаем стартовый индекс (сколько картинок было на предыдущих страницах)
                startIndex = parseInt($("#pptbook-start-index").text() || 0, 10);
            } catch (e) {
                items = [];
            }
        }
    }

    function show(idx) {
        if (!items.length) { return; }
        
        // Зацикливаем
        if (idx < 0) { idx = items.length - 1; }
        if (idx >= items.length) { idx = 0; }

        current = idx;
        $(SEL_img).attr("src", items[idx].src).attr("alt", items[idx].alt || "");
    }

    function open(localIdx) {
        const globalIdx = startIndex + localIdx; // Вычисляем глобальный индекс
        if (!items[globalIdx]) { return; }
        show(globalIdx);
        $(SEL_modal).css("display", "flex").attr("aria-hidden", "false");
        $("body").addClass("pptbook-modal-open");
    }

    function close() {
        $(SEL_modal).css("display", "none").attr("aria-hidden", "true");
        $(SEL_img).removeAttr("src");
        $("body").removeClass("pptbook-modal-open");
        current = -1;
    }

    return {
        init: function() {
            initData(); // Загружаем данные при старте

            $(document).on("click", SEL_link, function(e) {
                e.preventDefault();
                const localIdx = $(SEL_link).index(this); // Индекс на текущей странице (0-3)
                if (localIdx >= 0) { open(localIdx); }
            });

            $(document).on("click", SEL_modal, function(e) {
                const id = e.target.id;
                if (id === "pptbook-modal" || id === "pptbook-modal-img") {
                    close();
                }
            });

            $(document).on("click", SEL_prev, function(e) {
                e.stopPropagation();
                show(current - 1);
            });

            $(document).on("click", SEL_next, function(e) {
                e.stopPropagation();
                show(current + 1);
            });

            $(document).on("keyup", function(e) {
                if ($(SEL_modal).css("display") === "none") { return; }
                if (e.key === "Escape") { close(); }
                if (e.key === "ArrowLeft") { show(current - 1); }
                if (e.key === "ArrowRight") { show(current + 1); }
            });
        }
    };
});